INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist DDL nur für das Erstellen von Tabellen zuständig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Ändern und Löschen"}, {"text": "Ja", "correct": false, "because": "Umfasst mehr Funktionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Nutzung von DDL?', 3, '[{"text": "Strukturdefinition", "correct": true, "because": "Legt Datenbankgrundlage"}, {"text": "Schnelle Ausführung", "correct": false, "because": "Korrektheit wichtiger"}, {"text": "Minimale Befehle", "correct": false, "because": "Funktion zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Befehle gehören zu DDL?', 5, '[{"text": "CREATE", "correct": true, "because": "Erstellt Objekte"}, {"text": "ALTER", "correct": true, "because": "Ändert Struktur"}, {"text": "INSERT", "correct": false, "because": "DML-Befehl"}, {"text": "SELECT", "correct": false, "because": "DQL-Befehl"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DROP löscht Tabellen. b) DDL manipuliert Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "DDL ändert keine Daten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Arbeit mit DDL?', 4, '[{"text": "Tabellenstruktur", "correct": false, "because": "Kern der DDL"}, {"text": "Constraints", "correct": false, "because": "Sichern Integrität"}, {"text": "Farbanpassung", "correct": true, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DDL auch Datenbanken löschen kann?', 2, '[{"text": "Ja", "correct": true, "because": "DROP DATABASE möglich"}, {"text": "Nein", "correct": false, "because": "Teil der DDL"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Befehl wähle ich, um eine Tabelle zu ändern?', 3, '[{"text": "ALTER", "correct": true, "because": "Modifiziert Struktur"}, {"text": "CREATE", "correct": false, "because": "Nur Erstellung"}, {"text": "UPDATE", "correct": false, "because": "DML-Befehl"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringen mir DDL-Befehle?', 5, '[{"text": "Strukturierte Datenbank", "correct": true, "because": "Definiert Schema"}, {"text": "Flexibilität bei Änderungen", "correct": true, "because": "Anpassung möglich"}, {"text": "Schnelle Datenänderung", "correct": false, "because": "Nicht DDL-Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) CREATE definiert Tabellen. b) DDL fragt Daten ab. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Abfragen sind DQL"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für DDL?', 4, '[{"text": "Schema-Definition", "correct": false, "because": "Kern der DDL"}, {"text": "Tabellenänderung", "correct": false, "because": "Teil der DDL"}, {"text": "Spielemodus", "correct": true, "because": "Kein Datenbankzweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann DDL auch Daten einfügen?', 2, '[{"text": "Nein", "correct": true, "because": "Das ist DML"}, {"text": "Ja", "correct": false, "because": "Nur Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen DDL effektiv?', 4, '[{"text": "Präzise Definition", "correct": true, "because": "Sichert Struktur"}, {"text": "Constraints", "correct": true, "because": "Schützen Integrität"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Hardwareaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass DDL nur für Tabellen ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Views, Indizes"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der DDL-Nutzung?', 3, '[{"text": "Datenintegrität", "correct": true, "because": "Constraints sichern"}, {"text": "Schnelle Änderungen", "correct": false, "because": "Planung wichtiger"}, {"text": "Minimale Syntax", "correct": false, "because": "Struktur zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ALTER ändert Spalten. b) DDL verwaltet Berechtigungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Berechtigungen sind DCL"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Optionen verbessern DDL?', 5, '[{"text": "Constraints", "correct": true, "because": "Sichern Regeln"}, {"text": "Indizes", "correct": true, "because": "Optimieren Zugriff"}, {"text": "Manuelle Datenänderung", "correct": false, "because": "Nicht DDL"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei DDL unwichtig?', 3, '[{"text": "Tabellendefinition", "correct": false, "because": "Kern der DDL"}, {"text": "Strukturänderung", "correct": false, "because": "Teil der DDL"}, {"text": "GUI-Design", "correct": true, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann DDL rückgängig gemacht werden?', 3, '[{"text": "Nein", "correct": true, "because": "DDL ist meist nicht transaktional"}, {"text": "Ja", "correct": false, "because": "Nur mit Backup"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob DDL auch Views erstellen kann?', 2, '[{"text": "Ja", "correct": true, "because": "CREATE VIEW ist DDL"}, {"text": "Nein", "correct": false, "because": "Teil der DDL"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Befehl wähle ich, um eine Tabelle zu löschen?', 4, '[{"text": "DROP", "correct": true, "because": "Entfernt Objekte"}, {"text": "DELETE", "correct": false, "because": "DML-Befehl"}, {"text": "ALTER", "correct": false, "because": "Nur Änderung"}]');
